            for edge in edgeSet(molecule, ring) {
                molecule.bonds[edge].ring = true
            }
        }
        molecule.rings = selected
    }
    static func kekulize(_ molecule: Molecule, _ elements: Elements) throws {
        var remaining = Set(molecule.atoms.indices.filter {
            molecule.needsPi($0, elements, true)
        }), paired: [Int: Int] = [:]
        func matching(_ system: Set<Int>) -> Bool {
            guard let u = system.filter({
                paired[$0] == nil
            }).min() else {
                return true
            }
            for (v, edge) in molecule.neighbors[u] where system.contains(v) && paired[v] == nil && molecule.bonds[edge].kind == 4 {
                paired[u] = v;
                paired[v] = u
                if matching(system) {
                    return true
                }
                paired.removeValue(forKey: u);
                paired.removeValue(forKey: v)
            }
            return false
        }
        while let start = remaining.min() {
            var system: Set<Int> = [], stack = [start]
            remaining.remove(start)
            while let a = stack.popLast() {
                system.insert(a)
                for (b, edge) in molecule.neighbors[a] where molecule.bonds[edge].kind == 4 {
                    if remaining.remove(b) != nil {
                        stack.append(b)
                    }
                }
            }
            if !matching(system) {
                throw MoleculeError("kekulization failed", molecule.atoms[system.min()!].column)
            }
        }
        for i in molecule.bonds.indices {
            let bond = molecule.bonds[i]
            molecule.bonds[i].multiplicity = bond.kind == 4 ? (paired[bond.a] == bond.b ? 2 : 1) : bond.kind
        }
    }
}

import Foundation
enum Matcher {
    case any, aliphatic, aromatic, list([(String, Bool)])
}
struct Pattern {
    let graph: Molecule, atoms: [Matcher]
    static func parse(_ text: String, _ elements: Elements) throws -> Self {
        let parsed = try SmilesParser.parse(text, elements, pattern: true)
        return Self(graph: parsed.molecule, atoms: parsed.matchers)
    }
    static func molecule(_ molecule: Molecule) -> Self {
        Self(graph: molecule, atoms: molecule.atoms.map {
            .list([($0.element, $0.aromatic)])
        })
    }
}
struct Matches {
    let count: Int, unique: Int, first: [Int]
}
struct Fingerprint {
    var bits: Set<Int> = [];
    var paths = 0
}
enum Search {
    static func patternAtom(_ s: [UInt8], _ column: Int) throws -> (Matcher, Int) {
        switch s[0] {
            case 42: return (.any, 1)
            case 65: return (.aliphatic, 1)
            case 97: return (.aromatic, 1)
            case 91:
            guard let end = s.firstIndex(of: 93) else {
                throw MoleculeError("unclosed bracket", column)
            }
            if end == 1 {
                throw MoleculeError("bad bracket atom", column)
            }
            var list: [(String, Bool)] = []
            for part in s[1..<end].split(separator: 44, omittingEmptySubsequences: false) {
                guard let (element, aromatic, n) = SmilesParser.organic(Array(part)), n == part.count else {
                    throw MoleculeError("bad bracket atom", column)
                }
                list.append((element, aromatic))
            }
            return (.list(list), end + 1)
            default:
            guard let (element, aromatic, n) = SmilesParser.organic(s) else {
                throw MoleculeError("unexpected character", column)
            }
            return (.list([(element, aromatic)]), n)
        }
    }
    static func embeddings(_ pattern: Pattern, _ molecule: Molecule) -> Matches {
        var map: [Int] = [], used: Set<Int> = [], count = 0, sets: Set<[Int]> = [], first: [Int] = []
        func visit() {
            let a = map.count
            if a == pattern.atoms.count {
                count += 1
                if first.isEmpty {
                    first = map.map {
                        $0 + 1
                    }
                }
                sets.insert(map.sorted())
                return
            }
            for b in molecule.atoms.indices where !used.contains(b) {
                let atom = molecule.atoms[b], matches: Bool
                switch pattern.atoms[a] {
                    case .any: matches = true
                    case .aliphatic: matches = !atom.aromatic
                    case .aromatic: matches = atom.aromatic
                    case .list(let list): matches = list.contains {
                        $0.0 == atom.element && $0.1 == atom.aromatic
                    }
                }
                if !matches {
                    continue
                }
                let bonds = pattern.graph.neighbors[a].filter {
                    $0.0 < a
                }.allSatisfy {
                    v, edge in
                    guard let f = molecule.bond(b, map[v]) else {
                        return false
                    }
                    switch pattern.graph.bonds[edge].kind {
                        case 0: return molecule.bonds[f].kind == 1 || molecule.bonds[f].kind == 4
                        case 5: return true
                        case let kind: return molecule.bonds[f].kind == kind
                    }
                }
                if bonds {
                    used.insert(b);
                    map.append(b);
                    visit();
                    map.removeLast();
                    used.remove(b)
                }
            }
        }
        visit()
        return Matches(count: count, unique: sets.count, first: first)
    }
    static func fingerprint(_ molecule: Molecule, _ elements: Elements) -> Fingerprint {
        let codes = molecule.atoms.enumerated().map {
            16 * elements[$0.element.element]!.number + ($0.element.aromatic ? 8 : 0) + molecule.neighbors[$0.offset].count
        }
        var result = Fingerprint(), path: [Int] = []
        func walk(_ hash: Int) {
            result.paths += 1;
            result.bits.insert(hash % 1024)
            if path.count == 6 {
                return
            }
            let a = path.last!
            for (b, edge) in molecule.neighbors[a] where !path.contains(b) {
                let h = ((hash * 31 + molecule.bonds[edge].kind) % 1000003 * 31 + codes[b]) % 1000003
                path.append(b);
                walk(h);
                path.removeLast()
            }
        }
        for i in molecule.atoms.indices {
            path = [i];
            walk(codes[i])
        }
        return result
    }
    static func similarity(_ a: Fingerprint, _ b: Fingerprint) -> (Int, Int) {
        let common = a.bits.intersection(b.bits).count
        return (common, a.bits.count + b.bits.count - common)
    }
}

import Foundation
struct Parsed {
    let molecule: Molecule, matchers: [Matcher]
}
enum SmilesParser {
    static func organic(_ text: [UInt8]) -> (String, Bool, Int)? {
        if text.starts(with: [67, 108]) {
            return ("Cl", false, 2)
        }
        if text.starts(with: [66, 114]) {
            return ("Br", false, 2)
        }
        guard let c = text.first else {
            return nil
        }
        if Array("BCNOPSFI".utf8).contains(c) {
            return (String(UnicodeScalar(c)), false, 1)
        }
        if Array("bcnops".utf8).contains(c) {
            return (String(UnicodeScalar(c - 32)), true, 1)
        }
        return nil
    }
    static func atom(_ text: [UInt8], _ column: Int, _ elements: Elements) throws -> (Atom, Int) {
        if text[0] != 91 {
            guard let (element, aromatic, n) = organic(text) else {
                throw MoleculeError("unexpected character", column)
            }
            return (Atom(element: element, aromatic: aromatic, mass: 0, charge: 0, hydrogens: 0, bracket: false, column: column), n)
        }
        guard let end = text.firstIndex(of: 93) else {
            throw MoleculeError("unclosed bracket", column)
        }
        let s = Array(text[1..<end])
        var i = 0
        while i < s.count && (48...57).contains(s[i]) {
            i += 1
        }
        if i >= 4 || i > 0 && s[0] == 48 {
            throw MoleculeError("bad bracket atom", column)
        }
        let mass = i == 0 ? 0 : Int(String(bytes: s[..<i], encoding: .ascii)!)!
        if i == s.count {
            throw MoleculeError("bad bracket atom", column)
        }
        let element: String, aromatic: Bool
        if Array("bcnops".utf8).contains(s[i]) {
            element = String(UnicodeScalar(s[i] - 32));
            aromatic = true;
            i += 1
        }
        else if (65...90).contains(s[i]) {
            let one = String(UnicodeScalar(s[i]))
            if i + 1 < s.count && (97...122).contains(s[i + 1]), let two = String(bytes: s[i...i + 1], encoding: .ascii), elements[two] != nil {
                element = two;
                i += 2
            }
            else if elements[one] != nil {
                element = one;
                i += 1
            }
            else {
                throw MoleculeError("unknown element", column)
            }
            aromatic = false
        } else {
            throw MoleculeError("bad bracket atom", column)
        }
        if i < s.count && s[i] == 64 {
            i += 1;
            if i < s.count && s[i] == 64 {
                i += 1
            }
        }
        var hydrogens = 0
        if i < s.count && s[i] == 72 {
            hydrogens = 1;
            i += 1;
            if i < s.count && (48...57).contains(s[i]) {
                hydrogens = Int(s[i] - 48);
                i += 1
            }
        }
        var charge = 0
        if i < s.count && (s[i] == 43 || s[i] == 45) {
            let sign = s[i] == 43 ? 1 : -1
            i += 1
            var amount = 1
            if i < s.count && (49...57).contains(s[i]) {
                amount = Int(s[i] - 48);
                i += 1
            }
            charge = sign * amount
        }
        if i != s.count {
            throw MoleculeError("bad bracket atom", column)
        }
        return (Atom(element: element, aromatic: aromatic, mass: mass, charge: charge, hydrogens: hydrogens, bracket: true, column: column), end + 1)
    }
    static func symbol(_ c: UInt8, _ pattern: Bool) -> Int? {
        switch c {
            case 45: return 1
            case 61: return 2
            case 35: return 3
            case 58: return 4
            case 126 where pattern: return 5
            case 47, 92: return pattern ? nil : 1
            default: return nil
        }
    }
    static func parse(_ text: String, _ elements: Elements, pattern: Bool = false) throws -> Parsed {
        let s = Array(text.utf8), molecule = Molecule()
        var matchers: [Matcher] = [], current: Int?, pending: (Int, Int)?, branches: [(Int, Int)] = []
        var rings: [Int: (Int, (Int, Int)?, Int)] = [:], i = 0
        func add(_ a: Int, _ b: Int, _ kind: Int) {
            molecule.bonds.append(Bond(a: min(a, b), b: max(a, b), kind: kind))
        }
        while i < s.count {
            let c = s[i], column = i + 1
            if let kind = symbol(c, pattern) {
                if current == nil || pending != nil {
                    throw MoleculeError("misplaced bond", column)
                }
